pub struct Solution;

use std::collections::HashMap;

impl Solution {
    pub fn find_substring(s: String, words: Vec<String>) -> Vec<i32> {
        let mut result = Vec::new();
        if words.is_empty() || s.is_empty() {
            return result;
        }

        let word_len = words[0].len();
        let word_count = words.len();
        let total_len = word_len * word_count;

        if s.len() < total_len {
            return result;
        }

        let mut word_map: HashMap<&str, usize> = HashMap::new();
        for word in &words {
            *word_map.entry(word.as_str()).or_insert(0) += 1;
        }

        for offset in 0..word_len {
            let mut left = offset;
            let mut right = offset;
            let mut current_map: HashMap<&str, usize> = HashMap::new();
            let mut matched_words = 0;

            while right + word_len <= s.len() {
                let sub = &s[right..right + word_len];
                right += word_len;

                if let Some(&expected_count) = word_map.get(sub) {
                    *current_map.entry(sub).or_insert(0) += 1;
                    matched_words += 1;

                    while current_map[sub] > expected_count {
                        let left_word = &s[left..left + word_len];
                        *current_map.get_mut(left_word).unwrap() -= 1;
                        matched_words -= 1;
                        left += word_len;
                    }

                    if matched_words == word_count {
                        result.push(left as i32);
                    }
                } else {
                    current_map.clear();
                    matched_words = 0;
                    left = right;
                }
            }
        }

        result
    }
}

